.libPaths(c(Sys.getenv("WLIB"), .libPaths())); library(zujson)
t <- function(e) tryCatch(e, error = function(c) paste0("ERR[", class(c)[1], "] ", conditionMessage(c)))
for (f in c("ctl14.json","col14.json","ctl15.json","col15.json")) cat(f, system.time(json_parse_file(f, data_frame = TRUE))[["elapsed"]], "s\n")
options(zujson.max_df_cells = 4); cat("two 2x2 under budget 4:", t(length(json_parse('[[{"a":1,"b":2},{"a":3,"b":4}],[{"c":1,"d":2},{"c":3,"d":4}]]', data_frame=TRUE))), "\n"); options(zujson.max_df_cells = NULL)
x <- json_parse("[7908650058519908757503158852011, 7908650058519908757503158852011.0]"); cat("bignum:", sprintf("%a", x), " as.numeric:", sprintf("%a", as.numeric("7908650058519908757503158852011")), "\n")
key <- paste0("a", strrep("é", 40)); e <- tryCatch(json_parse(sprintf('[{"%s":1,"%s":2}]', key, key), data_frame = TRUE), error = identity); cat("msg class:", class(e)[1], " validUTF8:", validUTF8(conditionMessage(e)), "\n")
cat("ndjson NUL line:", t(json_parse_ndjson('1\n"\\u0000"\n')), "\n")
cat("ndjson depth line:", t(json_parse_ndjson(paste0("1\n", strrep("[",1001), strrep("]",1001)))), "\n")
cat("BOM-only first line:", t(json_parse_ndjson("\ufeff\n1")), "\n")
